document.getElementById("register-form")?.addEventListener("submit", function (e) {
  e.preventDefault(); // blokuje domyslne wyslanie formularza (i przeladowanie strony)

  const username = document.getElementById("username").value;
  console.log("Formularz przechwycony. Username:", username);
});

document.getElementById("register-form")?.addEventListener("submit", function (e) {
  console.log("e.target:", e.target);               // element formularza
  console.log("e.currentTarget:", e.currentTarget);  // rowniez element formularza (bo handler podpiety wprost tutaj)
});

document.getElementById("btn-right")?.addEventListener("contextmenu", (e) => {
  e.preventDefault(); // blokuje domyslne menu kontekstowe przegladarki
  console.log("Wlasna obsluga prawego przycisku");
});

document.getElementById("register-form")?.addEventListener("submit", function (e) {
  // BRAK e.preventDefault()!
  console.log("Obsluga formularza"); // to sie wykona, ALE strona i tak sie przeladuje
});

document.getElementById("register-form")?.addEventListener("submit", function (e) {
  e.preventDefault(); // POPRAWNIE - blokuje domyslne wyslanie i przeladowanie
  console.log("Obsluga formularza");
});

